using System;using System.Linq;using System.Windows.Forms;
namespace UrbanKaoz.DisplayRecorder {internal sealed partial class AudioMidiForm {void MusicalRowsR11(TableLayoutPanel grid){double bpm=tempo();if(double.IsNaN(bpm)||double.IsInfinity(bpm)||bpm<30||bpm>300)bpm=115;var model=new Synkoz.Montage();model.Beats.Add(new Synkoz.Beat936{Time=0,Beat=0});model.Beats.Add(new Synkoz.Beat936{Time=60/bpm,Beat=1});foreach(var label in grid.Controls.OfType<Label>().Where(l=>l.Text.EndsWith("(ms)")).ToArray()){int row=grid.GetRow(label);var number=grid.GetControlFromPosition(1,row) as NumericUpDown;if(number==null)continue;grid.Controls.Remove(number);label.Text=Synkoz.MusicalTimeR11.Title(label.Text);var musical=Synkoz.MusicalTimeR11.Editor(model,(double)number.Value/1000,(double)number.Minimum/1000,(double)number.Maximum/1000,v=>number.Value=Math.Max(number.Minimum,Math.Min(number.Maximum,(decimal)(v*1000))));musical.Dock=DockStyle.Fill;grid.Controls.Add(musical,1,row);musical.Enabled=number.Enabled;number.EnabledChanged+=delegate{musical.Enabled=number.Enabled;};}}}}
